    return {
      failedPanels: [],
      panelErrorTimeout: null
    }
  },
  computed: {
    apps() {
      const { openApps } = this.$ui
      return Object.values(openApps)
    },
    uiReady() {
      return this.$ui.uiReady
    },
    viewEditor() {
      return this.$storex.ui.viewEditor
    },
    failedPanelsMessage() {
      const count = this.failedPanels.length
      return count === 1
        ? `Failed to load panel: ${this.failedPanels[0]}`
        : `Failed to load ${count} panels`
    }
  },
  watch: {
    apps() {
      this.syncPanelsWithApps()
    },
    uiReady() {
      this.restoreLayout()
    },
    // CHANGED: Added watcher for activeProject to handle project switches
    'activeProject': async function(newProject, oldProject) {
      if (!newProject) return
      if (oldProject && newProject.project_id === oldProject.project_id) return

      // Project switched: load views from storage then restore with Desktop API
      await $storex.views.loadViewsForProject()
      this.restoreLayout()
    }
  },
  computed: {
    activeProject() {
      return this.$storex.projects?.activeProject
